package de.schaepi.puls180;
import android.app.*;import android.os.*;import android.bluetooth.*;import android.bluetooth.le.*;import android.content.*;import android.content.pm.PackageManager;import android.widget.*;import java.util.*;
public class BluetoothActivity extends FontActivity{
private final Handler autoHandler=new Handler();private boolean active=false;private Switch automatic;
private final Runnable autoConnect=new Runnable(){public void run(){if(!active)return;if(automatic.isChecked()&&connection==null&&!scanning&&!autoScanning&&hasWindowFocus())startAutoWait();autoHandler.postDelayed(this,15000);}};
private Button reconnect;private boolean reconnectRequested=false;private boolean autoScanning=false;private BluetoothLeScanner autoScanner;private TextView status;private ProgressBar searchSpinner;private LinearLayout received;private int count=0;private LinearLayout devices;private BluetoothAdapter adapter;private BluetoothLeScanner scanner;private BluetoothGatt connection;private final Handler handler=new Handler();private final Set<String> seen=new HashSet<>();private boolean scanning=false;private boolean receiverRegistered=false;private int generation=0;
private void message(String s){runOnUiThread(()->{if(!isDestroyed())status.setText(s);});}private void showSearching(boolean show){runOnUiThread(()->{if(!isDestroyed()&&searchSpinner!=null)searchSpinner.setVisibility(show?android.view.View.VISIBLE:android.view.View.GONE);});}
@Override public void onCreate(Bundle state){super.onCreate(state);ScrollView scroll=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(28,40,28,32);scroll.addView(root);if(Build.VERSION.SDK_INT>=30)scroll.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets i=insets.getInsets(android.view.WindowInsets.Type.systemBars());v.setPadding(i.left,i.top,i.right,i.bottom);return insets;});setContentView(scroll);TextView title=new TextView(this);title.setText("Bluetooth-Gerät hinzufügen");title.setTextSize(24);root.addView(title);TextView help=new TextView(this);help.setText("Dein Bluetooth-Blutdruckmessgerät in den Übertragungs- oder Kopplungsmodus bringen. Die App sucht gleichzeitig nach normalen Bluetooth- und BLE-Geräten. Namenlose Geräte werden mit ihrer Bluetooth-Adresse angezeigt. Einmal suchen und das passende Gerät auswählen; danach lauscht die App stromsparend nur nach diesem gespeicherten Gerät. Erst wenn das Messgerät beim Übertragen sichtbar wird, verbindet sie sich. Die App empfängt die vom Gerät gesendeten Messwerte. Bitte diese Ansicht während der Übertragung offen lassen.");help.setTextSize(17);root.addView(help);automatic=new Switch(this);automatic.setText("Verbinden, wenn das Messgerät sendet");automatic.setChecked(getSharedPreferences("bluetooth",0).getBoolean("automatic",true));int[][] switchStates={new int[]{android.R.attr.state_checked},new int[]{}};automatic.setThumbTintList(new android.content.res.ColorStateList(switchStates,new int[]{android.graphics.Color.rgb(25,112,220),android.graphics.Color.rgb(150,160,172)}));automatic.setTrackTintList(new android.content.res.ColorStateList(switchStates,new int[]{android.graphics.Color.rgb(105,175,245),android.graphics.Color.rgb(205,212,220)}));root.addView(automatic);automatic.setOnCheckedChangeListener((button,enabled)->{getSharedPreferences("bluetooth",0).edit().putBoolean("automatic",enabled).apply();autoHandler.removeCallbacks(autoConnect);if(enabled&&active)autoHandler.postDelayed(autoConnect,500);else if(!enabled){cleanup();message("Automatisches Verbinden ausgeschaltet.");}});reconnect=new Button(this);reconnect.setAllCaps(false);reconnect.setText("Mit gespeichertem Gerät verbinden");root.addView(reconnect);reconnect.setOnClickListener(v->reconnectSaved());Button scan=new Button(this);scan.setAllCaps(false);scan.setText("Geräte suchen");root.addView(scan);scan.setOnClickListener(v->begin());Button phoneBluetooth=new Button(this);phoneBluetooth.setAllCaps(false);phoneBluetooth.setText("Alle Geräte im Handy-Bluetooth anzeigen");root.addView(phoneBluetooth);phoneBluetooth.setOnClickListener(v->startActivity(new Intent(android.provider.Settings.ACTION_BLUETOOTH_SETTINGS)));Button stop=new Button(this);stop.setAllCaps(false);stop.setText("Suche / Verbindung beenden");root.addView(stop);stop.setOnClickListener(v->{automatic.setChecked(false);cleanup();message("Beendet. Zum automatischen Verbinden den Schalter wieder einschalten.");});LinearLayout searchState=new LinearLayout(this);searchState.setOrientation(LinearLayout.HORIZONTAL);searchState.setGravity(android.view.Gravity.CENTER_VERTICAL);searchSpinner=new ProgressBar(this);searchSpinner.setIndeterminate(true);searchSpinner.setVisibility(android.view.View.GONE);int spinnerSize=(int)(32*getResources().getDisplayMetrics().density);LinearLayout.LayoutParams spinnerParams=new LinearLayout.LayoutParams(spinnerSize,spinnerSize);spinnerParams.setMargins(0,0,(int)(8*getResources().getDisplayMetrics().density),0);searchState.addView(searchSpinner,spinnerParams);status=new TextView(this);status.setTextSize(17);status.setText("Bereit zur Suche.");searchState.addView(status,new LinearLayout.LayoutParams(0,-2,1f));root.addView(searchState);devices=new LinearLayout(this);devices.setOrientation(1);received=new LinearLayout(this);received.setOrientation(1);root.addView(received);root.addView(devices);Button back=new Button(this);back.setAllCaps(false);back.setText("Zurück zu meinen Werten");back.setTextColor(android.graphics.Color.WHITE);back.setBackgroundTintList(android.content.res.ColorStateList.valueOf(android.graphics.Color.rgb(35,155,80)));root.addView(back);back.setOnClickListener(v->finish());BluetoothManager manager=getSystemService(BluetoothManager.class);adapter=manager==null?null:manager.getAdapter();android.content.IntentFilter foundFilter=new android.content.IntentFilter(BluetoothDevice.ACTION_FOUND);foundFilter.addAction(BluetoothAdapter.ACTION_DISCOVERY_FINISHED);if(Build.VERSION.SDK_INT>=33)registerReceiver(classicReceiver,foundFilter,RECEIVER_NOT_EXPORTED);else registerReceiver(classicReceiver,foundFilter);receiverRegistered=true;updateSavedLabel();}
private void updateSavedLabel(){String name=getSharedPreferences("bluetooth",0).getString("name","");reconnect.setText(name.isEmpty()?"Mit gespeichertem Gerät verbinden":"Verbinden: "+name);}
private final ScanCallback autoSignal=new ScanCallback(){@Override public void onScanResult(int type,ScanResult result){runOnUiThread(()->{if(!autoScanning||!active||connection!=null)return;BluetoothDevice device=result.getDevice();String name=getSharedPreferences("bluetooth",0).getString("name","Gespeichertes Gerät");stopAutoWait();connect(device,name);});}@Override public void onScanFailed(int error){runOnUiThread(()->{autoScanning=false;autoScanner=null;message("Bluetooth-Warten wurde unterbrochen. Schalter kurz aus- und einschalten.");});}};
private void startAutoWait(){if(!granted()||adapter==null||!adapter.isEnabled())return;String address=getSharedPreferences("bluetooth",0).getString("device","");if(!BluetoothAdapter.checkBluetoothAddress(address))return;try{autoScanner=adapter.getBluetoothLeScanner();if(autoScanner==null)return;ScanFilter filter=new ScanFilter.Builder().setDeviceAddress(address).build();ScanSettings settings=new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_POWER).build();autoScanner.startScan(java.util.Collections.singletonList(filter),settings,autoSignal);autoScanning=true;message("Warte stromsparend auf ein Signal vom gespeicherten Messgerät …");}catch(SecurityException|IllegalStateException e){autoScanning=false;autoScanner=null;}}
private void stopAutoWait(){if(autoScanner!=null&&autoScanning)try{autoScanner.stopScan(autoSignal);}catch(SecurityException|IllegalStateException ignored){}autoScanning=false;autoScanner=null;}private void reconnectSaved(){reconnectRequested=true;if(!granted()){requestPermissions(bluetoothPermissions(),51);return;}String address=getSharedPreferences("bluetooth",0).getString("device","");String name=getSharedPreferences("bluetooth",0).getString("name","Gespeichertes Gerät");if(!BluetoothAdapter.checkBluetoothAddress(address)){message("Bitte dein Gerät einmal suchen und auswählen. Danach wird es gespeichert.");return;}if(adapter==null){message("Bluetooth nicht verfügbar.");return;}if(!adapter.isEnabled()){startActivity(new Intent(BluetoothAdapter.ACTION_REQUEST_ENABLE));message("Bluetooth einschalten, dann auf Verbinden tippen.");return;}connect(adapter.getRemoteDevice(address),name);}
private boolean granted(){return Build.VERSION.SDK_INT<31?checkSelfPermission("android.permission.ACCESS_FINE_LOCATION")==PackageManager.PERMISSION_GRANTED:checkSelfPermission("android.permission.BLUETOOTH_SCAN")==PackageManager.PERMISSION_GRANTED&&checkSelfPermission("android.permission.BLUETOOTH_CONNECT")==PackageManager.PERMISSION_GRANTED;} private String[] bluetoothPermissions(){return Build.VERSION.SDK_INT<31?new String[]{"android.permission.ACCESS_FINE_LOCATION"}:new String[]{"android.permission.BLUETOOTH_SCAN","android.permission.BLUETOOTH_CONNECT"};}
private void begin(){reconnectRequested=false;if(!granted()){requestPermissions(bluetoothPermissions(),51);return;}if(adapter==null){message("Bluetooth wird auf diesem Handy nicht unterstützt.");return;}if(!adapter.isEnabled()){startActivity(new Intent(BluetoothAdapter.ACTION_REQUEST_ENABLE));message("Bitte Bluetooth einschalten und erneut suchen.");return;}cleanup();seen.clear();devices.removeAllViews();showBonded();try{adapter.cancelDiscovery();adapter.startDiscovery();scanner=adapter.getBluetoothLeScanner();if(scanner==null){message("Bluetooth-Suche nicht verfügbar.");return;}scanning=true;showSearching(true);scanner.startScan(null,new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).setCallbackType(ScanSettings.CALLBACK_TYPE_ALL_MATCHES).setMatchMode(ScanSettings.MATCH_MODE_AGGRESSIVE).setNumOfMatches(ScanSettings.MATCH_NUM_MAX_ADVERTISEMENT).build(),callback);message("Suche 30 Sekunden lang …");handler.postDelayed(()->{if(scanning){stopScan();message(seen.isEmpty()?"Kein Gerät gefunden. Übertragungs- oder Kopplungsmodus prüfen und erneut suchen.":"Suche beendet. "+seen.size()+" Geräte gefunden. Tippe auf dein Gerät.");}},30000);}catch(SecurityException|IllegalStateException e){scanning=false;showSearching(false);message("Suche fehlgeschlagen. Bluetooth-Freigabe prüfen.");}}
@Override public void onRequestPermissionsResult(int code,String[] p,int[] result){super.onRequestPermissionsResult(code,p,result);if(code==51){if(granted()){if(reconnectRequested)reconnectSaved();else begin();}else message("Bitte Zugriff auf Geräte in der Nähe erlauben.");}}
private final BroadcastReceiver classicReceiver=new BroadcastReceiver(){@Override public void onReceive(Context context,Intent intent){if(BluetoothDevice.ACTION_FOUND.equals(intent.getAction())){BluetoothDevice device=Build.VERSION.SDK_INT>=33?intent.getParcelableExtra(BluetoothDevice.EXTRA_DEVICE,BluetoothDevice.class):(BluetoothDevice)intent.getParcelableExtra(BluetoothDevice.EXTRA_DEVICE);if(device==null)return;try{String name=Build.VERSION.SDK_INT>=30?device.getAlias():null;if(name==null)name=device.getName();if(name==null||name.trim().isEmpty())name=device.getAddress();addDevice(device,name,"Handy-Bluetooth");}catch(SecurityException ignored){}}}};
private void showBonded(){try{for(BluetoothDevice device:adapter.getBondedDevices()){String name=device.getName();addDevice(device,name==null?"Unbenanntes gekoppeltes Gerät":name,"Bereits gekoppelt");}}catch(SecurityException ignored){}}
private void addDevice(BluetoothDevice device,String name,String source){String address=device.getAddress();if(!seen.add(address))return;final String label=name;Button item=new Button(this);item.setAllCaps(false);item.setTextSize(15);item.setGravity(android.view.Gravity.START|android.view.Gravity.CENTER_VERTICAL);int pad=(int)(12*getResources().getDisplayMetrics().density);item.setPadding(pad,0,pad,0);item.setText(name.equals(address)?source+"\n"+address:name+"\n"+source+" · "+address);item.setOnClickListener(v->connect(device,label));devices.addView(item,new LinearLayout.LayoutParams(-1,(int)(62*getResources().getDisplayMetrics().density)));}
private final ScanCallback callback=new ScanCallback(){@Override public void onScanResult(int type,ScanResult result){runOnUiThread(()->{if(!scanning||isDestroyed())return;BluetoothDevice device=result.getDevice();try{String name=result.getScanRecord()==null?null:result.getScanRecord().getDeviceName();if(name==null&&Build.VERSION.SDK_INT>=30)name=device.getAlias();if(name==null)name=device.getName();boolean unnamed=name==null||name.trim().isEmpty();if(unnamed&&result.getRssi()<-70)return;if(unnamed)name=device.getAddress();addDevice(device,name,(unnamed?"Unbenannt":"Signal")+" · "+result.getRssi()+" dBm");}catch(SecurityException e){message("Bluetooth-Freigabe fehlt.");}});}@Override public void onScanFailed(int error){scanning=false;showSearching(false);message("Suche fehlgeschlagen, Code "+error+". Bitte erneut versuchen.");}};
private void connect(BluetoothDevice device,String name){cleanup();count=0;int current=++generation;message("Verbinde mit "+name+" …");try{connection=device.connectGatt(this,false,new BluetoothGattCallback(){@Override public void onConnectionStateChange(BluetoothGatt g,int status,int state){runOnUiThread(()->{if(current!=generation)return;if(status!=BluetoothGatt.GATT_SUCCESS){message(count>0?count+" Messwerte gespeichert. Verbindung danach beendet (Code "+status+").":"Verbindung beendet, Code "+status+". Keine Messwerte empfangen. Gerät aktivieren und erneut verbinden.");cleanup();return;}if(state==BluetoothProfile.STATE_CONNECTED){message("Verbunden. Prüfe Übertragungsdienste …");if(!g.discoverServices()){message("Dienste konnten nicht abgefragt werden.");cleanup();}}else if(state==BluetoothProfile.STATE_DISCONNECTED){message("Gerät hat die Verbindung beendet. "+count+" Messwerte empfangen. Bitte diese Meldung melden, wenn es 0 sind.");cleanup();}});}@Override public void onServicesDiscovered(BluetoothGatt g,int result){runOnUiThread(()->{if(current!=generation)return;handler.removeCallbacksAndMessages(null);if(result!=BluetoothGatt.GATT_SUCCESS){message("Dienstprüfung fehlgeschlagen: "+result);cleanup();return;}BluetoothGattService service=g.getService(UUID.fromString("00001810-0000-1000-8000-00805f9b34fb"));BluetoothGattCharacteristic measurement=service==null?null:service.getCharacteristic(UUID.fromString("00002a35-0000-1000-8000-00805f9b34fb"));
if(measurement==null){message("Kein unterstützter Messwertkanal gefunden.");cleanup();return;}BluetoothGattDescriptor cccd=measurement.getDescriptor(UUID.fromString("00002902-0000-1000-8000-00805f9b34fb"));
if(cccd==null||(measurement.getProperties()&BluetoothGattCharacteristic.PROPERTY_INDICATE)==0){message("Messwertkanal unterstützt keine Standard-Übertragung.");cleanup();return;}
getSharedPreferences("bluetooth",0).edit().putString("device",device.getAddress()).putString("name",name).apply();updateSavedLabel();if(!g.setCharacteristicNotification(measurement,true)){message("Empfang konnte nicht aktiviert werden.");cleanup();return;}
if(Build.VERSION.SDK_INT>=33){int code=g.writeDescriptor(cccd,BluetoothGattDescriptor.ENABLE_INDICATION_VALUE);if(code!=BluetoothStatusCodes.SUCCESS){message("Empfangsfreigabe fehlgeschlagen: "+code);cleanup();return;}}else{cccd.setValue(BluetoothGattDescriptor.ENABLE_INDICATION_VALUE);if(!g.writeDescriptor(cccd)){message("Empfangsfreigabe fehlgeschlagen.");cleanup();return;}}message("Aktiviere Messwertempfang …");handler.postDelayed(()->{if(current==generation){message("Keine Antwort auf die Empfangsfreigabe. Bitte erneut verbinden.");cleanup();}},15000);
});}
@Override public void onDescriptorWrite(BluetoothGatt g,BluetoothGattDescriptor descriptor,int code){runOnUiThread(()->{if(current!=generation)return;handler.removeCallbacksAndMessages(null);if(code!=BluetoothGatt.GATT_SUCCESS){message("Empfangsfreigabe abgelehnt: "+code+". Kopplung am Gerät prüfen.");cleanup();return;}message("Auslesebereit: Empfangsfreigabe vom Gerät bestätigt. Warte auf Messwerte vom Blutdruckmessgerät …");try{BluetoothGattService svc=g.getService(UUID.fromString("00001810-0000-1000-8000-00805f9b34fb"));BluetoothGattCharacteristic feat=svc==null?null:svc.getCharacteristic(UUID.fromString("00002a49-0000-1000-8000-00805f9b34fb"));if(feat!=null)g.readCharacteristic(feat);}catch(SecurityException ignored){}handler.postDelayed(()->{if(current==generation){message("Empfang beendet. "+count+" Messwerte empfangen. Falls keine Werte kamen, Übertragung am Gerät erneut starten.");cleanup();}},120000);});}
@Override public void onCharacteristicRead(BluetoothGatt g,BluetoothGattCharacteristic c,byte[] value,int status){if(!c.getUuid().equals(UUID.fromString("00002a49-0000-1000-8000-00805f9b34fb"))||status!=BluetoothGatt.GATT_SUCCESS||value.length<2)return;boolean supported=(value[0]&4)!=0;runOnUiThread(()->{if(current!=generation)return;getSharedPreferences("bluetooth",0).edit().putBoolean("irregular:"+device.getAddress(),supported).apply();});}
@Override public void onCharacteristicChanged(BluetoothGatt g,BluetoothGattCharacteristic c,byte[] value){if(!c.getUuid().equals(UUID.fromString("00002a35-0000-1000-8000-00805f9b34fb")))return;byte[] copy=value.clone();runOnUiThread(()->{if(current!=generation)return;try{BleMeasurement m=BleMeasurement.parse(copy);try(DirectStore store=new DirectStore(BluetoothActivity.this)){store.save(m,device.getAddress(),copy);}count++;TextView row=new TextView(BluetoothActivity.this);row.setText(m.display());row.setTextSize(21);row.setPadding(0,16,0,16);received.addView(row,0);message(count+" Messwerte direkt empfangen. Auf dem Handy gespeichert und in der Hauptliste verfügbar.");}catch(Exception e){message("Messwert konnte nicht gespeichert werden: "+e.getClass().getSimpleName()+". Bitte Ansicht offen lassen.");}});}
},BluetoothDevice.TRANSPORT_LE);if(connection==null){message("Verbindung konnte nicht gestartet werden.");return;}handler.postDelayed(()->{if(current==generation){message("Zeitüberschreitung. Bitte Übertragungsmodus prüfen.");cleanup();}},25000);}catch(SecurityException e){message("Bluetooth-Freigabe fehlt.");cleanup();}}
private void stopScan(){if(scanner!=null&&scanning){try{scanner.stopScan(callback);}catch(SecurityException|IllegalStateException ignored){}}scanning=false;showSearching(false);}
private void cleanup(){generation++;handler.removeCallbacksAndMessages(null);stopAutoWait();try{if(adapter!=null)adapter.cancelDiscovery();}catch(SecurityException ignored){}stopScan();if(connection!=null){try{connection.disconnect();connection.close();}catch(SecurityException ignored){}connection=null;}}
@Override protected void onResume(){super.onResume();stopService(new Intent(this,MeasurementService.class));if(licenseBlocked())return;active=true;autoHandler.removeCallbacks(autoConnect);autoHandler.postDelayed(autoConnect,700);}
@Override protected void onStop(){active=false;autoHandler.removeCallbacks(autoConnect);super.onStop();cleanup();}
@Override protected void onPause(){cleanup();MeasurementService.ensure(this);super.onPause();}
@Override protected void onDestroy(){if(receiverRegistered){try{unregisterReceiver(classicReceiver);}catch(IllegalArgumentException ignored){}receiverRegistered=false;}super.onDestroy();}
}














